// No node counts words or checks fact ids against the brief.
const s = $('Editor notes').first().json.json;
const brief = $('Claim').first().json.brief;
const words = (s.scenes ?? []).map((x) => x.narration ?? '').join(' ').split(/\s+/).filter(Boolean).length;
const rules = [];
if (words < 90 || words > 140) rules.push('narration is ' + words + ' words; it must be 90-140');
if (String(s.title ?? '').length > 70) rules.push('title is longer than 70 characters');
const nf = (brief.facts ?? []).length;
for (const sc of s.scenes ?? []) for (const f of sc.fact_ids ?? []) if (!(Number.isInteger(f) && f >= 0 && f < nf)) rules.push('scene ' + sc.id + ' cites fact ' + f + ', which the brief does not have');
return [{ json: { rules, words } }];

// No node merges the Checker's JSON with the code rule checks.
const c = $input.first().json;
const rules = $('Rules notes').first().json.rules;
const script = $('Editor notes').first().json.json;
const pass = c.json?.pass === true && rules.length === 0;
const flags = [...(c.json?.unsupported_claims ?? []), ...(c.json?.policy_issues ?? []), ...rules].map(String);
return [{ json: { script, check: { ...c.json, rules, pass }, pass, flags,
  writer_agent: 'editor', writer_provider: $('Editor notes').first().json.provider, checker_provider: c.provider } }];

